226	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
227	    @Override
228	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
229	        // Idempotent create: when the request carries an 'Idempotency-Key' already seen, return the
230	        // originally created owner with 200 instead of creating (and duplicate-checking) a new one.
231	        String idempotencyKey = currentIdempotencyKey();
232	        if (idempotencyKey != null) {
233	            Integer existingId = idempotencyKeyToOwnerId.get(idempotencyKey);
234	            if (existingId != null) {
235	                Owner existingOwner = this.clinicService.findOwnerById(existingId);
236	                if (existingOwner != null) {
237	                    populateHouseholdSize(existingOwner);
238	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existingOwner), HttpStatus.OK);
239	                }
240	            }
241	        }
242	        List<String> missingFields = new ArrayList<>();
243	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
244	            missingFields.add("firstName");
245	        }
246	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
247	            missingFields.add("lastName");
248	        }
249	        // Normalize each supplied address form up front. The structured fields are preferred when
250	        // present; the flat 'address' input remains accepted for backward compatibility. An owner is
251	        // valid when it supplies an address in EITHER form (a non-blank addressLine1, or the flat
252	        // address). A whitespace-only value collapses to the empty string and counts as absent.
253	        String normalizedAddressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
254	        String normalizedAddressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
255	        String normalizedFlatAddress = normalizeAddress(ownerFieldsDto.getAddress());
256	        boolean hasStructuredAddress = StringUtils.hasText(normalizedAddressLine1);
257	        boolean hasFlatAddress = StringUtils.hasText(normalizedFlatAddress);
258	        if (!hasStructuredAddress && !hasFlatAddress) {
259	            missingFields.add("address");
260	        }
261	        // Compose the stored/returned address: the structured lines when present (addressLine1, with a
262	        // single space and addressLine2 appended when addressLine2 is present), otherwise the flat form.
263	        String composedAddress;
264	        if (hasStructuredAddress) {
265	            composedAddress = StringUtils.hasText(normalizedAddressLine2)
266	                ? normalizedAddressLine1 + " " + normalizedAddressLine2
267	                : normalizedAddressLine1;
268	        } else {
269	            composedAddress = normalizedFlatAddress;
270	        }
271	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
272	            missingFields.add("city");
273	        }
274	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
275	            missingFields.add("telephone");
276	        }
277	        if (!missingFields.isEmpty()) {
278	            throw new InvalidRequestException(missingFields);
279	        }
280	        HttpHeaders headers = new HttpHeaders();
281	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
282	        // A newly created owner is never soft-deleted.
283	        owner.setDeleted(false);
284	        // Store (and later return) the normalized structured lines and the composed address. The
285	        // structured lines are kept only when the structured form was supplied; otherwise they are
286	        // cleared so the response reflects the flat form that was actually used.
287	        owner.setAddressLine1(hasStructuredAddress ? normalizedAddressLine1 : null);
288	        owner.setAddressLine2(hasStructuredAddress && StringUtils.hasText(normalizedAddressLine2)
289	            ? normalizedAddressLine2 : null);
290	        owner.setAddress(composedAddress);
291	        // Normalize the telephone into E.164 form (reject with 400 when it cannot form a valid one).
292	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
293	        owner.setTelephone(normalizedTelephone);
294	        // Normalize the (optional) email: reject a syntactically invalid address, otherwise store it lower-cased.
295	        owner.setEmail(normalizeEmail(owner.getEmail()));
296	        // Validate the (optional) postcode: reject with 400 when present but malformed or out of range
297	        // for the city's region. The value (mapped straight from the request) is stored and returned as given.
298	        validatePostcode(owner.getCity(), owner.getPostcode());
299	        // Reject a supplied registration date that lies in the future (later than the server's current
300	        // date) with a 400 Bad Request. Checked against the raw supplied value, before defaulting below.
301	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(LocalDate.now())) {
302	            throw new InvalidRequestException(List.of("registrationDate"));
303	        }
304	        // Default the (optional) registration date to the server's current date when none was supplied.
305	        if (owner.getRegistrationDate() == null) {
306	            owner.setRegistrationDate(LocalDate.now());
307	        }
308	        // The effective registration date must fall on a business day: when it lands on a Saturday,
309	        // Sunday or a listed public holiday (whether supplied or defaulted above), roll it forward to
310	        // the next non-holiday business day. Every value derived from the registration date below
311	        // (daily create-limit, member id) uses this adjusted date.
312	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
313	        // Reject the request once the maximum number of owners for the owner's registration day has
314	        // been reached (100 or more owners already created on that date).
315	        int ownersRegisteredToday = countOwnersRegisteredOn(owner.getRegistrationDate());
316	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
317	            throw new DailyOwnerLimitException(owner.getRegistrationDate());
318	        }
319	        // Flag a bulk-signup warning when more than 80 owners had already been created on this
320	        // owner's registration day at the moment this owner was created; otherwise clear it.
321	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
322	        // Reject the request when the owner's city has already reached its owner capacity.
323	        int ownersInCity = countOwnersInCity(owner.getCity());
324	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
325	            throw new CityCapacityException(owner.getCity());
326	        }
327	        // Flag a capacity warning when the owner's city already holds between 40 and 49 owners
328	        // (approaching the hard limit of 50) at the moment this owner was created; otherwise clear it.
329	        owner.setCapacityWarning(ownersInCity >= CAPACITY_WARNING_THRESHOLD && ownersInCity < MAX_OWNERS_PER_CITY);
330	        // The household is keyed deterministically on (normalizedLastName, postcode): the householdId
331	        // is the first 12 hex characters of the SHA-256 digest of '<normalizedLastName>|<postcode>',
332	        // so any two owners with the same last name and postcode automatically resolve to the same
333	        // household without an explicit opt-in. It is assigned up front so it feeds the household-size
334	        // read-back, the membership-level cap and the household-of-3 points. It is NO LONGER part of
335	        // duplicate detection: that is expressed solely through the identity key below.
336	        String householdId = generateHouseholdId(owner.getLastName(), owner.getPostcode());
337	        owner.setHouseholdId(householdId);
338	        // All duplicate detection is consolidated into this single derived identity key: the SHA-256
339	        // hex of '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'. Reject with 409 only when
340	        // the new owner's WHOLE identity key exactly matches a non-deleted existing owner's. Because
341	        // the telephone is part of the key, two owners with the same last name and postcode but
342	        // different telephones have different keys and are both allowed (the second is a soft match,
343	        // see below); only an exact full-key match is a hard duplicate.
344	        String identityKey = owner.getIdentityKey();
345	        boolean identityCollision = this.clinicService.findAllOwners().stream()
346	            .filter(existing -> !existing.isDeleted())
347	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
348	        if (identityCollision) {
349	            throw new DuplicateIdentityException(identityKey);
350	        }
351	        // Soft-match detection: the new owner is not a hard (identity-key) duplicate, but it may
352	        // still be a likely duplicate of an existing owner. Flag it when an existing owner shares
353	        // this owner's soundex(lastName) and postcode while carrying a DIFFERENT identity key. When
354	        // several existing owners match, the one with the lowest id is chosen so the result is
355	        // deterministic.
356	        Owner softMatch = findPossibleDuplicate(owner);
357	        if (softMatch != null) {
358	            owner.setPossibleDuplicate(true);
359	            owner.setPossibleDuplicateOf(softMatch.getId());
360	        } else {
361	            owner.setPossibleDuplicate(false);
362	        }
363	        // Record how many existing owners already share this first name and last name
364	        // (compared case-insensitively) before this owner is created.
365	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
366	        // Assign the unified member id '<REGION><FY><HASH8><CHK>' before persisting.
367	        owner.setMemberId(generateMemberId(owner));
368	        this.clinicService.saveOwner(owner);
369	        // Remember the created owner under the request's idempotency key so a later create repeating
370	        // the same key returns this owner instead of creating a duplicate.
371	        if (idempotencyKey != null) {
372	            idempotencyKeyToOwnerId.put(idempotencyKey, owner.getId());
373	        }
374	        populateHouseholdSize(owner);
375	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
376	        // Cap the new owner's membership level at one above the current maximum among their
377	        // existing household members (no cap when the household has no other member).
378	        applyHouseholdMembershipCap(owner, ownerDto);
379	        // Emit an audit line carrying the new owner's id, unified member id, registration date
380	        // and numeric membership level.
381	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
382	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
383	            ownerDto.getMembershipLevel());
384	        // Besides the human-readable audit line, emit an immutable structured event carrying a
385	        // monotonically increasing sequence number, the owner id, the owner's primary identifier
386	        // (the unified member id) and the numeric membership level. Serialized once, up front, so
387	        // the logged event cannot change.
388	        AUDIT.info(ownerCreatedEvent(AUDIT_EVENT_SEQ.incrementAndGet(), owner.getId(),
389	            owner.getMemberId(), ownerDto.getMembershipLevel()));
390	        // Enqueue a welcome notification for the newly created owner, carrying the owner id and member id.
391	        NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
392	        headers.setLocation(UriComponentsBuilder.newInstance()
393	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
394	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
395	    }
396	
397	    /**
398	     * Build the immutable structured {@code OWNER_CREATED} audit event as a JSON object string:
399	     * {@code {seq, ownerId, memberId, membershipLevel, event:'OWNER_CREATED'}}. The
400	     * {@code memberId} field carries the owner's primary identifier (the unified member id), so the
401	     * event always names the owner's canonical identity. A {@code null} membership level is
402	     * serialized as JSON {@code null}.
403	     *
404	     * @param seq             the monotonically increasing event sequence number
405	     * @param ownerId         the created owner's id
406	     * @param primaryId       the owner's primary identifier (member id)
407	     * @param membershipLevel the owner's numeric membership level, may be {@code null}
408	     * @return the JSON-serialized event
409	     */
410	    private String ownerCreatedEvent(long seq, Integer ownerId, String primaryId, Integer membershipLevel) {
411	        return "{\"seq\":" + seq
412	            + ",\"ownerId\":" + ownerId
413	            + ",\"memberId\":" + jsonString(primaryId)
414	            + ",\"membershipLevel\":" + (membershipLevel == null ? "null" : membershipLevel)
415	            + ",\"event\":\"OWNER_CREATED\"}";
416	    }
417	
418	    /**
419	     * Render a nullable string as a JSON value: {@code null} for a {@code null} input, otherwise the
420	     * value wrapped in double quotes with the JSON-significant characters escaped.
421	     *
422	     * @param value the value to render, may be {@code null}
423	     * @return the JSON string literal (or the token {@code null})
424	     */
425	    private String jsonString(String value) {
426	        if (value == null) {
427	            return "null";
428	        }
429	        StringBuilder sb = new StringBuilder(value.length() + 2);
430	        sb.append('"');
431	        for (int i = 0; i < value.length(); i++) {
432	            char c = value.charAt(i);
433	            switch (c) {
434	                case '"' -> sb.append("\\\"");
435	                case '\\' -> sb.append("\\\\");
436	                case '\n' -> sb.append("\\n");
437	                case '\r' -> sb.append("\\r");
438	                case '\t' -> sb.append("\\t");
439	                default -> {
440	                    if (c < 0x20) {
441	                        sb.append(String.format("\\u%04x", (int) c));
442	                    } else {
443	                        sb.append(c);
444	                    }
445	                }
446	            }
447	        }
448	        sb.append('"');
449	        return sb.toString();
450	    }
