545	    /**
546	     * Generate the unified member id formatted {@code <REGION><FY><HASH8><CHK>}, where {@code REGION}
547	     * is the region code derived from the owner's identity (postcode range first, then the
548	     * city-to-region table, otherwise {@code UNKNOWN}), {@code FY} is the two-digit fiscal year that
549	     * the owner's business-day-adjusted registration date falls in, {@code HASH8} is the first eight
550	     * upper-case hex characters of the SHA-256 digest of {@code normalizedTelephone + lastName} (the
551	     * same HASH8 the region-and-hash identity uses), and {@code CHK} is a single Luhn check digit
552	     * computed over the digits of {@code <REGION><FY><HASH8>} (e.g. {@code NSW271A2B3C4D5}).
553	     *
554	     * @param owner the owner whose (already-normalized) telephone, last name, postcode, city and
555	     *              registration date are read
556	     * @return the generated (collision-free) member id
557	     */
558	    private String generateMemberId(Owner owner) {
559	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
560	        String fy = String.format("%02d", fiscalYear(owner.getRegistrationDate()) % 100);
561	        String hash8 = shortSha256Hex(owner.getTelephone() + owner.getLastName(), 8);
562	        String base = region + fy + hash8;
563	        String memberId = base + luhnCheckDigit(base);
564	        return deduplicateMemberId(memberId);
565	    }
566	
567	    /**
568	     * Return a member id that does not collide with any existing owner's member id. When the given
569	     * base id is already unique it is returned unchanged; otherwise {@code -<n>} is appended with the
570	     * smallest {@code n} of 2 or more that makes the result unique (e.g. {@code NSW271A2B3C4D5}, then
571	     * {@code NSW271A2B3C4D5-2}, {@code NSW271A2B3C4D5-3}, ...). The incoming owner is not yet
572	     * persisted, so it never counts as a collision with itself.
573	     *
574	     * @param baseId the computed {@code <REGION><FY><HASH8><CHK>} member id
575	     * @return the de-duplicated member id
576	     */
577	    private String deduplicateMemberId(String baseId) {
578	        java.util.Set<String> existingIds = this.clinicService.findAllOwners().stream()
579	            .map(Owner::getMemberId)
580	            .filter(java.util.Objects::nonNull)
581	            .collect(java.util.stream.Collectors.toSet());
582	        if (!existingIds.contains(baseId)) {
583	            return baseId;
584	        }
585	        int n = 2;
586	        String candidate = baseId + "-" + n;
587	        while (existingIds.contains(candidate)) {
588	            n++;
589	            candidate = baseId + "-" + n;
590	        }
591	        return candidate;
592	    }
