594	    /**
595	     * Compute the single Luhn check digit (0-9) over the digits contained in the given value.
596	     * Non-digit characters are ignored. A {@code null} or digit-free value yields a check digit of 0.
597	     *
598	     * @param value the value whose digits the check digit is computed over
599	     * @return the Luhn check digit
600	     */
601	    private int luhnCheckDigit(String value) {
602	        if (value == null) {
603	            return 0;
604	        }
605	        int sum = 0;
606	        boolean doubleDigit = true;
607	        for (int i = value.length() - 1; i >= 0; i--) {
608	            char c = value.charAt(i);
609	            if (c < '0' || c > '9') {
610	                continue;
611	            }
612	            int digit = c - '0';
613	            if (doubleDigit) {
614	                digit *= 2;
615	                if (digit > 9) {
616	                    digit -= 9;
617	                }
618	            }
619	            sum += digit;
620	            doubleDigit = !doubleDigit;
621	        }
622	        return (10 - (sum % 10)) % 10;
623	    }
