625	    /**
626	     * Derive the region code for an owner's identity. The postcode is preferred: when present and it
627	     * falls within a known region's inclusive 4-digit range (NSW 2000-2099, VIC 3000-3099,
628	     * QLD 4000-4099) that region is returned. Otherwise fall back to the pinned city-to-region table
629	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD), and finally {@code UNKNOWN} for a city with no
630	     * known region.
631	     *
632	     * @param postcode the owner's postcode, may be {@code null}
633	     * @param city     the owner's city
634	     * @return the derived region code
635	     */
636	    private String deriveRegion(String postcode, String city) {
637	        if (postcode != null && POSTCODE_PATTERN.matcher(postcode).matches()) {
638	            int value = Integer.parseInt(postcode);
639	            for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
640	                int[] range = entry.getValue();
641	                if (value >= range[0] && value <= range[1]) {
642	                    return entry.getKey();
643	                }
644	            }
645	        }
646	        String region = CITY_REGION.get(city);
647	        return region != null ? region : "UNKNOWN";
648	    }
