650	    /**
651	     * Return the first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
652	     * bytes of {@code input}.
653	     *
654	     * @param input  the value to digest
655	     * @param length the number of leading hex characters to return
656	     * @return the truncated upper-case hex digest
657	     */
658	    private String shortSha256Hex(String input, int length) {
659	        try {
660	            byte[] digest = MessageDigest.getInstance("SHA-256")
661	                .digest(input.getBytes(StandardCharsets.UTF_8));
662	            StringBuilder sb = new StringBuilder(digest.length * 2);
663	            for (byte b : digest) {
664	                sb.append(String.format("%02x", b));
665	            }
666	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
667	        } catch (java.security.NoSuchAlgorithmException e) {
668	            throw new IllegalStateException("SHA-256 not available", e);
669	        }
670	    }
