672	    /**
673	     * Roll a registration date forward onto a business day: a Saturday, Sunday or listed public
674	     * holiday is advanced day-by-day until it lands on the next non-holiday weekday, while a date
675	     * that is already a non-holiday weekday is returned unchanged. This is the effective registration
676	     * date that is stored, returned and used for every value derived from it.
677	     *
678	     * @param date the effective registration date (supplied or defaulted)
679	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
680	     */
681	    private LocalDate rollToBusinessDay(LocalDate date) {
682	        while (!isBusinessDay(date)) {
683	            date = date.plusDays(1);
684	        }
685	        return date;
686	    }
