688	    /**
689	     * A business day is a weekday (Monday to Friday) that is not a listed public holiday.
690	     *
691	     * @param date the date to test
692	     * @return {@code true} when the date is a non-holiday weekday
693	     */
694	    private boolean isBusinessDay(LocalDate date) {
695	        DayOfWeek dayOfWeek = date.getDayOfWeek();
696	        if (dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY) {
697	            return false;
698	        }
699	        return !PUBLIC_HOLIDAYS.contains(date);
700	    }
