702	    /**
703	     * The fiscal year that the given date falls in. The fiscal year starts on 1 July, so a date in
704	     * July to December belongs to the fiscal year ending in the following calendar year, and a date
705	     * in January to June belongs to the fiscal year ending in the same calendar year. The fiscal
706	     * year is identified by that ending calendar year (e.g. 1 July 2026 to 30 June 2027 is 2027).
707	     *
708	     * @param date the date whose fiscal year is required
709	     * @return the fiscal year's ending calendar year
710	     */
711	    private int fiscalYear(LocalDate date) {
712	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
