800	    /**
801	     * Normalize an owner address for storage: trim and collapse every internal run of whitespace to a
802	     * single space, upper-case the result and expand common street-type abbreviations token by token
803	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value normalizes
804	     * to the empty string. The result is the canonical form that is stored, returned and used for every
805	     * address comparison (household duplicate detection and the shared household id).
806	     *
807	     * @param address the raw address, may be {@code null}
808	     * @return the normalized address
809	     */
810	    private String normalizeAddress(String address) {
811	        if (address == null) {
812	            return "";
813	        }
814	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
815	        if (collapsed.isEmpty()) {
816	            return "";
817	        }
818	        String[] tokens = collapsed.split(" ");
819	        StringBuilder sb = new StringBuilder(collapsed.length());
820	        for (int i = 0; i < tokens.length; i++) {
821	            if (i > 0) {
822	                sb.append(' ');
823	            }
824	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
825	        }
826	        return sb.toString();
827	    }
