843	    /**
844	     * Normalize an optional owner email address. A blank/absent value is treated as "not provided"
845	     * and returns {@code null}. When present, the value must be a syntactically valid address; if it
846	     * is not, an {@link InvalidRequestException} is thrown (mapped to 400 Bad Request). A valid value
847	     * is returned lower-cased.
848	     *
849	     * @param email the raw email from the request payload, may be {@code null}
850	     * @return the lower-cased email, or {@code null} when none was provided
851	     */
852	    private String normalizeEmail(String email) {
853	        if (!StringUtils.hasText(email)) {
854	            return null;
855	        }
856	        if (!EMAIL_PATTERN.matcher(email).matches()) {
857	            throw new InvalidRequestException(List.of("email"));
858	        }
859	        String lowerCased = email.toLowerCase(Locale.ROOT);
860	        // Reject an address whose domain is on the disposable-domain blocklist.
861	        String domain = lowerCased.substring(lowerCased.indexOf('@') + 1);
862	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
863	            throw new InvalidRequestException(List.of("email"));
864	        }
865	        return lowerCased;
866	    }
