868	    /**
869	     * Validate an optional owner postcode. A blank/absent value is treated as "not provided" and
870	     * passes (postcode is optional). When present it must be exactly four digits, and when the owner's
871	     * city has a known region (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) the postcode must fall within
872	     * that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known
873	     * region accepts any 4-digit postcode. A violation throws an {@link InvalidRequestException} (mapped
874	     * to 400 Bad Request).
875	     *
876	     * @param city     the owner's city (used to resolve the region)
877	     * @param postcode the raw postcode from the request payload, may be {@code null}
878	     */
879	    private void validatePostcode(String city, String postcode) {
880	        if (!StringUtils.hasText(postcode)) {
881	            return;
882	        }
883	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
884	            throw new InvalidRequestException(List.of("postcode"));
885	        }
886	        String region = CITY_REGION.get(city);
887	        int[] range = region == null ? null : REGION_POSTCODE_RANGE.get(region);
888	        if (range != null) {
889	            int value = Integer.parseInt(postcode);
890	            if (value < range[0] || value > range[1]) {
891	                throw new InvalidRequestException(List.of("postcode"));
892	            }
893	        }
894	    }
