896	    /**
897	     * Normalize a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value that
898	     * already carries a leading '+' keeps its country code; otherwise the default country code
899	     * ({@code +61}) is assumed and a single leading '0' is dropped from the national digits. The
900	     * result must be a '+' followed by 8 to 15 digits, otherwise an {@link InvalidRequestException}
901	     * is thrown (mapped to 400 Bad Request).
902	     *
903	     * @param telephone the raw telephone from the request payload
904	     * @return the E.164 string (e.g. {@code +61412345678})
905	     */
906	    private String normalizeTelephone(String telephone) {
907	        String cleaned = TELEPHONE_SEPARATORS.matcher(telephone).replaceAll("");
908	        String candidate;
909	        if (cleaned.startsWith("+")) {
910	            candidate = cleaned;
911	        } else {
912	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
913	            candidate = "+" + DEFAULT_COUNTRY_CODE + national;
914	        }
915	        if (!E164_PATTERN.matcher(candidate).matches()) {
916	            throw new InvalidRequestException(List.of("telephone"));
917	        }
918	        // For country codes with a known fixed national-number length, reject a candidate whose
919	        // national digits (everything after the '+' and the country code) do not match that length.
920	        String digits = candidate.substring(1);
921	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
922	            String countryCode = entry.getKey();
923	            if (digits.startsWith(countryCode)) {
924	                int nationalLength = digits.length() - countryCode.length();
925	                if (nationalLength != entry.getValue()) {
926	                    throw new InvalidRequestException(List.of("telephone"));
927	                }
928	                break;
929	            }
930	        }
931	        return candidate;
932	    }
